const preview = (name, alt, eager = false, cls = '') => `<figure class="feature-media ${cls}" style="--image-ratio:${sizes.get(name).width / sizes.get(name).height}"><button class="image-preview" data-preview aria-label="Enlarge ${alt}">${screenshot(name, alt, eager)}</button><figcaption><span>Wixal ${captureVersion(name)}</span><button data-preview>View full size ${external}</button></figcaption></figure>`;
