const products = [
  { id: 'desktop', label: 'Desktop', title: 'Your project, in one place.', copy: 'Open a folder and work with its files, images, and conversations. Add relevant files to a prompt and return to saved conversations.', facts: ['Project files', 'Image attachments', 'Saved conversations'], action: 'Explore Wixal Desktop', href: url('product/#desktop'), image: 'workspace', alt: 'The redesigned Wixal 0.7.3 main workspace.' },
  { id: 'models', label: 'Models', title: 'Find the model that fits.', copy: 'Use the included local engine, download or import models, and switch models in a saved chat. Measure performance on this Mac.', facts: ['Local inference', 'Hardware fit', 'Same-chat switching'], action: 'Explore models & performance', href: url('models/'), image: 'models-focus', alt: 'The actual Wixal Models page with installed models and context controls.' },
  { id: 'memory', label: 'Memory', title: 'Keep the useful context.', copy: 'Choose project and global memory, set a size budget, and carry a reviewed summary into a fresh chat when context fills up.', facts: ['Project scopes', 'Small global profile', 'Context handoff'], action: 'Explore project memory', href: url('product/#memory'), image: 'memory-scopes', alt: 'Wixal 0.7.7 project memory scope, size choices, saved capacity and editable note.' },
  { id: 'commands', label: 'Commands', title: 'Run commands. Keep the output.', copy: 'Use the interactive terminal yourself, or review commands and follow their output in chat. Save useful execution records to your project.', facts: ['Interactive terminal', 'Reviewed sessions', 'Retained output'], action: 'Explore command workflows', href: url('tools/#commands'), image: 'terminal-focus', alt: 'An actual passing node --test run in the Wixal terminal.' },
  { id: 'web', label: 'Web & tools', title: 'Read pages. Work with APIs.', copy: 'Inspect rendered pages, search for sources, make reviewed API requests, and connect trusted MCP tools.', facts: ['Rendered pages', 'Web & APIs', 'External MCP'], action: 'Explore web & external tools', href: url('tools/#web'), image: 'browser-card-focus', alt: 'The actual reviewed browser-inspection control in Wixal’s tool kit.' },
  { id: 'companion', label: 'Companion', title: 'Send a task from ChatGPT.', copy: 'Share selected project context and send a task to your Wixal inbox. Start it in the app and review the requested actions.', facts: ['Selected projects', 'Task inbox', 'Optional connection'], action: 'Set up the companion', href: url('product/#companion') }
];
