function productOverview(copy) {
  return `<section id="capabilities" class="section container detail-section capabilities-section"><div class="overview-heading"><div><p class="eyebrow">The Wixal workspace</p><h2>One app.<br>More ways to work.</h2></div><p>${copy}</p></div>${productGrid()}</section>`;
}
function sectionHeading(title, copy) { return `<div class="section-heading"><h2>${title}</h2>${copy ? `<p>${copy}</p>` : ''}</div>`; }
function principles() {
  return `<section class="section container">${sectionHeading('Keep the context. Review the work.', 'Your project, your model, and decisions you can return to.')}<div class="principles"><article><h3>Context that carries forward</h3><p>Save project notes, search earlier conversations, and inspect saved summaries when a chat grows.</p></article><article><h3>Actions you can review</h3><p>Choose available tools. Review file edits, commands, memory saves, and network or external tool calls.</p></article><article><h3>Local by choice</h3><p>Run models with the included engine. Chats and project notes stay on your Mac. A short global profile can sync to your Wixal account.</p></article></div></section>`;
}
