function document(page) {
  const canonical = `${origin}${url(page.path)}`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${page.title}</title><meta name="description" content="${page.description}"><meta name="ga-measurement-id" content="${measurementId}"><meta name="theme-color" content="#f7f7f4"><meta property="og:type" content="website"><meta property="og:title" content="${page.title}"><meta property="og:description" content="${page.description}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${origin}${assetUrl('assets/social-card.png')}"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="${canonical}"><link rel="icon" href="${url('assets/favicon.svg')}" type="image/svg+xml"><script>try{const t=localStorage.getItem("wixal-site-theme");if(t==="dark"||t==="light")document.documentElement.dataset.theme=t}catch{}</script><link rel="stylesheet" href="${assetUrl('styles.css')}"><script type="module" src="${assetUrl('site.js')}"></script><script type="module" src="${assetUrl('analytics.js')}"></script>${['', 'download/', 'stats/'].includes(page.path) ? `<script type="module" src="${assetUrl('totals.js')}"></script>` : ''}${page.path === 'stats/' ? `<script type="module" src="${assetUrl('stats.js')}"></script>` : ''}</head><body>${header(page.active)}<main id="main">${page.content}</main>${footer()}<aside class="analytics-choice" data-analytics-choice aria-label="Website analytics preferences" hidden><p>Allow optional analytics to help us understand website visits and download clicks? <a href="${url('privacy/')}">Privacy details</a></p><div><button data-analytics-deny>Decline</button><button data-analytics-allow>Allow analytics</button><button data-analytics-close aria-label="Close analytics preferences" hidden>Close</button></div></aside><dialog class="preview-dialog" aria-label="Wixal screenshot preview"><div class="preview-toolbar"><p>Inside Wixal</p><button data-preview-close aria-label="Close screenshot preview">Close ×</button></div><div class="preview-image"><img alt=""></div><p class="preview-description"></p></dialog></body></html>`;
}
